<script setup>
import { Search, UserRound } from '@lucide/vue';
import { onMounted, ref, watch } from 'vue';
import AppButton from '../../components/ui/AppButton.vue';
import StatusPill from '../../components/ui/StatusPill.vue';
import { api, getApiError } from '../../services/api.js';
import { useUiStore } from '../../stores/ui.js';
const ui=useUiStore();const users=ref([]);const meta=ref({});const search=ref('');const role=ref('');const loading=ref(true);let debounce;
async function load(page=1){loading.value=true;try{const response=await api.get('/admin/users',{params:{page,search:search.value||undefined,role:role.value||undefined}});users.value=response.data.data;meta.value=response.data.meta;}finally{loading.value=false}}
watch([search,role],()=>{clearTimeout(debounce);debounce=setTimeout(()=>load(),300)});onMounted(load);
async function toggle(user){const status=user.accountStatus==='active'?'suspended':'active';if(!window.confirm(`${status==='suspended'?'Suspend':'Reactivate'} this account?`))return;try{const response=await api.patch(`/admin/users/${user._id}/status`,{status});user.accountStatus=response.data.data.user.accountStatus;ui.notify('Account status updated.','success')}catch(error){ui.notify(getApiError(error).message,'error')}}
</script>
<template><section class="page admin-page"><div class="page-header"><div><span class="eyebrow">Account controls</span><h1 class="page-title">User management</h1><p class="muted">Search, review, suspend, and reactivate accounts.</p></div></div><div class="filters card"><label><Search :size="18" /><input v-model="search" placeholder="Search name, email, or phone" /></label><select v-model="role" aria-label="Filter by role"><option value="">All roles</option><option value="commuter">Commuters</option><option value="driver">Drivers</option><option value="admin">Admins</option></select></div><div class="table-card card"><div v-if="loading" class="skeleton" style="height:300px"></div><table v-else><thead><tr><th>User</th><th>Role</th><th>Status</th><th>Joined</th><th></th></tr></thead><tbody><tr v-for="user in users" :key="user._id"><td><div class="identity"><span><UserRound :size="18" /></span><div><strong>{{ user.firstName }} {{ user.lastName }}</strong><small>{{ user.email || user.phone }}</small></div></div></td><td class="capitalize">{{ user.role }}</td><td><StatusPill :status="user.accountStatus" /></td><td>{{ new Date(user.createdAt).toLocaleDateString('en-PH') }}</td><td><AppButton size="sm" :variant="user.accountStatus==='active'?'danger':'secondary'" @click="toggle(user)">{{ user.accountStatus==='active'?'Suspend':'Reactivate' }}</AppButton></td></tr></tbody></table><div v-if="!loading&&!users.length" class="empty-state">No users match these filters.</div></div><div class="pagination"><AppButton size="sm" variant="outline" :disabled="meta.page<=1" @click="load(meta.page-1)">Previous</AppButton><span>Page {{ meta.page||1 }} of {{ meta.pages||1 }}</span><AppButton size="sm" variant="outline" :disabled="meta.page>=meta.pages" @click="load(meta.page+1)">Next</AppButton></div></section></template>
<style scoped>.admin-page{max-width:1200px}.filters{display:grid;gap:10px;padding:12px;margin-bottom:15px}.filters label{display:flex;align-items:center;gap:9px;padding:0 11px;border:1px solid var(--color-border);border-radius:11px;color:var(--color-text-soft)}.filters input,.filters select,select{height:42px;border:0;outline:0;background:white}.filters input{width:100%}.filters select,select{padding:0 12px;border:1px solid var(--color-border);border-radius:11px}.table-card{overflow-x:auto}table{width:100%;border-collapse:collapse;white-space:nowrap}th,td{padding:13px 15px;border-bottom:1px solid var(--color-border);font-size:.75rem;text-align:left}th{color:var(--color-text-soft);font-size:.65rem;text-transform:uppercase}tr:last-child td{border:0}.identity{display:flex;align-items:center;gap:10px}.identity>span{display:grid;width:36px;height:36px;place-items:center;border-radius:50%;background:#d1fae5;color:var(--color-primary-dark)}.identity>div{display:grid;gap:3px}.identity small{color:var(--color-text-soft)}.capitalize{text-transform:capitalize}.pagination{display:flex;align-items:center;justify-content:flex-end;gap:12px;margin-top:14px}.pagination span{color:var(--color-text-soft);font-size:.7rem}@media(min-width:650px){.filters{grid-template-columns:1fr 180px}}</style>

